import React, { useState, useMemo } from 'react';
import { Modal } from './components/Modal';
import { History, DownloadCloud, UploadCloud, FileText, Database, Trash2, AlertCircle, Search, Filter } from 'lucide-react';

const STORAGE_KEY = 'accpro_backup_history';

// Load history from localStorage
export const getBackupHistory = () => {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        return raw ? JSON.parse(raw) : [];
    } catch { return []; }
};

// Add a new history entry
export const addBackupHistoryEntry = (entry) => {
    try {
        const history = getBackupHistory();
        history.unshift({
            id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
            timestamp: new Date().toISOString(),
            ...entry,
        });
        // Keep last 200 entries
        if (history.length > 200) history.length = 200;
        localStorage.setItem(STORAGE_KEY, JSON.stringify(history));
    } catch (e) {
        console.warn('[BackupHistory] Failed to save entry:', e);
    }
};

// Clear all history
export const clearBackupHistory = () => {
    try {
        localStorage.removeItem(STORAGE_KEY);
    } catch { }
};

const ACTION_ICONS = {
    backup: { icon: DownloadCloud, color: 'text-blue-600', bg: 'bg-blue-100', label: 'Backup' },
    restore: { icon: UploadCloud, color: 'text-orange-600', bg: 'bg-orange-100', label: 'Restore' },
    export_voucher: { icon: FileText, color: 'text-cyan-600', bg: 'bg-cyan-100', label: 'Export Voucher' },
    import_voucher: { icon: Database, color: 'text-emerald-600', bg: 'bg-emerald-100', label: 'Import Voucher' },
};

const formatDate = (iso) => {
    try {
        const d = new Date(iso);
        return d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
    } catch { return iso; }
};

export default function BackupHistoryModal({ isOpen, onClose }) {
    const [search, setSearch] = useState('');
    const [filterAction, setFilterAction] = useState('all');
    const [showClearConfirm, setShowClearConfirm] = useState(false);

    const history = useMemo(() => {
        if (!isOpen) return [];
        return getBackupHistory();
    }, [isOpen]);

    const filtered = useMemo(() => {
        let items = history;
        if (filterAction !== 'all') {
            items = items.filter(e => e.action === filterAction);
        }
        if (search.trim()) {
            const q = search.toLowerCase();
            items = items.filter(e =>
                (e.details || '').toLowerCase().includes(q) ||
                (e.type || '').toLowerCase().includes(q) ||
                (e.action || '').toLowerCase().includes(q)
            );
        }
        return items;
    }, [history, search, filterAction]);

    const handleClear = () => {
        clearBackupHistory();
        setShowClearConfirm(false);
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Backup / Restore History" maxWidth="max-w-2xl" zIndex={60}>
            <div className="space-y-4 p-1">
                {/* Summary bar */}
                <div className="flex items-center justify-between">
                    <p className="text-xs text-gray-500">
                        <span className="font-semibold">{history.length}</span> total activities logged
                    </p>
                    {history.length > 0 && (
                        <button
                            onClick={() => setShowClearConfirm(true)}
                            className="flex items-center gap-1 px-2.5 py-1.5 rounded-lg border border-red-200 text-red-500 text-[10px] font-bold hover:bg-red-50 transition-colors"
                        >
                            <Trash2 size={12} /> Clear All
                        </button>
                    )}
                </div>

                {/* Filters */}
                <div className="flex gap-3 items-center">
                    <div className="relative flex-1">
                        <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                        <input
                            type="text"
                            placeholder="Search history..."
                            value={search}
                            onChange={e => setSearch(e.target.value)}
                            className="w-full pl-9 pr-3 py-2 border border-gray-200 rounded-lg text-xs focus:ring-2 focus:ring-blue-200 focus:border-blue-400 outline-none"
                        />
                    </div>
                    <div className="flex gap-1">
                        {[
                            { key: 'all', label: 'All' },
                            { key: 'backup', label: 'Backup' },
                            { key: 'restore', label: 'Restore' },
                            { key: 'export_voucher', label: 'Export' },
                            { key: 'import_voucher', label: 'Import' },
                        ].map(f => (
                            <button
                                key={f.key}
                                onClick={() => setFilterAction(f.key)}
                                className={`px-2.5 py-1.5 rounded-lg border text-[10px] font-bold transition-colors ${
                                    filterAction === f.key
                                        ? 'bg-blue-600 text-white border-blue-600'
                                        : 'bg-white text-gray-500 border-gray-200 hover:border-blue-300'
                                }`}
                            >
                                {f.label}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Clear confirmation */}
                {showClearConfirm && (
                    <div className="bg-red-50 border border-red-200 rounded-xl p-4 flex items-center justify-between">
                        <div className="flex items-center gap-2 text-sm text-red-700">
                            <AlertCircle size={18} />
                            <span>Clear all backup history? This cannot be undone.</span>
                        </div>
                        <div className="flex gap-2">
                            <button onClick={() => setShowClearConfirm(false)} className="px-3 py-1.5 rounded-lg border border-gray-200 text-xs font-bold bg-white text-gray-600 hover:bg-gray-50">Cancel</button>
                            <button onClick={handleClear} className="px-3 py-1.5 rounded-lg bg-red-600 text-white text-xs font-bold hover:bg-red-700">Clear All</button>
                        </div>
                    </div>
                )}

                {/* History list */}
                {filtered.length === 0 ? (
                    <div className="text-center py-12 text-gray-400">
                        <History size={40} className="mx-auto mb-3 opacity-30" />
                        <p className="text-sm font-medium">No backup history found</p>
                        <p className="text-xs mt-1">Activities will appear here when you backup, restore, export, or import data.</p>
                    </div>
                ) : (
                    <div className="space-y-2 max-h-[400px] overflow-y-auto pr-1">
                        {filtered.map((entry) => {
                            const actionDef = ACTION_ICONS[entry.action] || { icon: History, color: 'text-gray-600', bg: 'bg-gray-100', label: entry.action };
                            const Icon = actionDef.icon;
                            return (
                                <div key={entry.id} className="flex gap-3 p-3 rounded-xl border border-gray-100 hover:border-gray-200 hover:bg-gray-50/50 transition-all">
                                    <div className={`w-9 h-9 rounded-lg ${actionDef.bg} flex items-center justify-center shrink-0`}>
                                        <Icon size={16} className={actionDef.color} />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center justify-between gap-2">
                                            <span className="text-sm font-bold text-gray-800">{actionDef.label}</span>
                                            <span className="text-[10px] text-gray-400 whitespace-nowrap">{formatDate(entry.timestamp)}</span>
                                        </div>
                                        {entry.details && (
                                            <p className="text-xs text-gray-500 mt-0.5 truncate">{entry.details}</p>
                                        )}
                                        <div className="flex items-center gap-2 mt-1.5 flex-wrap">
                                            {entry.type && (
                                                <span className="text-[10px] px-2 py-0.5 rounded-full bg-gray-100 text-gray-600 font-medium">{entry.type}</span>
                                            )}
                                            {entry.count !== undefined && (
                                                <span className="text-[10px] px-2 py-0.5 rounded-full bg-blue-100 text-blue-600 font-medium">{entry.count} records</span>
                                            )}
                                            {entry.collection && (
                                                <span className="text-[10px] px-2 py-0.5 rounded-full bg-purple-100 text-purple-600 font-medium">{entry.collection}</span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </Modal>
    );
}
